// Package postgres implements app.Store and app.CredentialStore against
// PostgreSQL via jackc/pgx. The queries are generated by sqlc from
// queries.sql.
package postgres

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/lib/errorx"
	"github.com/garamsh/garam/lib/grn"
	"github.com/garamsh/garam/platform/internal/app"
	"github.com/garamsh/garam/platform/internal/app/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
	"github.com/garamsh/garam/platform/internal/pgxtype"
)

// Store implements app.Store and app.CredentialStore.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time checks that Store satisfies both stores.
var (
	_ app.Store           = (*Store)(nil)
	_ app.CredentialStore = (*Store)(nil)
)

// New constructs a Postgres-backed app store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}

// GetApp reads the app under g.
func (s *Store) GetApp(ctx context.Context, g grn.GRN) (*app.App, error) {
	row, err := s.q.GetApp(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get app", app.ErrAppNotFound, nil)
	}
	return rowToApp(row)
}

// ListApps reads the apps orgGRN may see.
func (s *Store) ListApps(ctx context.Context, orgGRN grn.GRN) ([]*app.App, error) {
	rows, err := s.q.ListApps(ctx, pgtype.Text{String: orgGRN.String(), Valid: true})
	if err != nil {
		return nil, pgxerr.Classify(err, "list apps", nil, nil)
	}
	return each(rows, rowToApp)
}

// CreateInstallation inserts the installation and answers the row it
// wrote.
func (s *Store) CreateInstallation(ctx context.Context, i *app.Installation) (*app.Installation, error) {
	scope, projects := "organization", []string{}
	if !i.Scope.IsOrganization() {
		scope = "projects"
		for _, p := range i.Scope.Projects() {
			projects = append(projects, p.String())
		}
	}
	row, err := s.q.CreateInstallation(ctx, db.CreateInstallationParams{
		Grn:         i.GRN.String(),
		OrgGrn:      i.Organization.String(),
		AppGrn:      i.App.String(),
		Scope:       scope,
		ProjectGrns: projects,
		CreatedBy:   i.CreatedBy.String(),
		CreatedAt:   pgxtype.Timestamptz(i.CreatedAt),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "create installation", nil, app.ErrInstallationExists)
	}
	return rowToInstallation(row)
}

// GetInstallation reads the installation under g.
func (s *Store) GetInstallation(ctx context.Context, g grn.GRN) (*app.Installation, error) {
	row, err := s.q.GetInstallation(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get installation", app.ErrInstallationNotFound, nil)
	}
	return rowToInstallation(row)
}

// ListInstallations reads the organization's installations.
func (s *Store) ListInstallations(ctx context.Context, orgGRN grn.GRN) ([]*app.Installation, error) {
	rows, err := s.q.ListInstallations(ctx, orgGRN.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "list installations", nil, nil)
	}
	return each(rows, rowToInstallation)
}

// DeleteInstallation removes the installation under g, and its
// instances with it, in one transaction holding the installation's
// row, and answers the instances it removed.
func (s *Store) DeleteInstallation(ctx context.Context, g grn.GRN) ([]grn.GRN, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)
	n, err := q.LockInstallation(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "lock installation", nil, nil)
	}
	if n == 0 {
		return nil, app.ErrInstallationNotFound
	}
	removed, err := q.DeleteInstallationInstances(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "delete instances", nil, nil)
	}
	if _, err := q.DeleteInstallation(ctx, g.String()); err != nil {
		return nil, pgxerr.Classify(err, "delete installation", nil, nil)
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, errorx.Wrap(err, "commit", errorx.KindUnavailable)
	}
	return storedGRNs("instance", removed...)
}

// CreateInstance inserts the instance where its app's instance setting
// admits one more, in one transaction holding the installation's row.
func (s *Store) CreateInstance(ctx context.Context, i *app.Instance) (*app.Instance, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := s.q.WithTx(tx)
	held, err := q.HoldInstallation(ctx, i.Installation.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "hold installation", app.ErrInstallationNotFound, nil)
	}
	count, err := q.CountInstances(ctx, i.Installation.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "count instances", nil, nil)
	}
	if err := app.Instances(held).Admit(int(count)); err != nil {
		return nil, err
	}
	row, err := q.CreateInstance(ctx, db.CreateInstanceParams{
		Grn:             i.GRN.String(),
		OrgGrn:          i.Organization.String(),
		InstallationGrn: i.Installation.String(),
		CreatedBy:       i.CreatedBy.String(),
		CreatedAt:       pgxtype.Timestamptz(i.CreatedAt),
		Name:            i.Name,
		Description:     i.Description,
		Kind:            i.Kind,
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "create instance", nil, nil)
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, errorx.Wrap(err, "commit", errorx.KindUnavailable)
	}
	return rowToInstance(row)
}

// GetInstance reads the instance under g.
func (s *Store) GetInstance(ctx context.Context, g grn.GRN) (*app.Instance, error) {
	row, err := s.q.GetInstance(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get instance", app.ErrInstanceNotFound, nil)
	}
	return rowToInstance(row)
}

// ListInstances reads the installation's instances, ordered by GRN.
func (s *Store) ListInstances(ctx context.Context, installation grn.GRN) ([]*app.Instance, error) {
	rows, err := s.q.ListInstances(ctx, installation.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "list instances", nil, nil)
	}
	return each(rows, rowToInstance)
}

// LastContact reads the time ResolveToken last recorded for g.
func (s *Store) LastContact(ctx context.Context, g grn.GRN) (*time.Time, error) {
	rows, err := s.q.GetInstanceContact(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get instance contact", nil, nil)
	}
	if len(rows) == 0 {
		return nil, nil
	}
	at := rows[0].Time.UTC()
	return &at, nil
}

// UpdateInstance writes the name, description and kind patch sets.
func (s *Store) UpdateInstance(ctx context.Context, g grn.GRN, patch app.DetailsPatch) (*app.Instance, error) {
	row, err := s.q.UpdateInstance(ctx, db.UpdateInstanceParams{
		Name:        optionalText(patch.Name()),
		Description: optionalText(patch.Description()),
		Kind:        optionalText(patch.Kind()),
		Grn:         g.String(),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "update instance", app.ErrInstanceNotFound, nil)
	}
	return rowToInstance(row)
}

// DeleteInstance removes the record under g.
func (s *Store) DeleteInstance(ctx context.Context, g grn.GRN) error {
	n, err := s.q.DeleteInstance(ctx, g.String())
	if err != nil {
		return pgxerr.Classify(err, "delete instance", nil, nil)
	}
	if n == 0 {
		return app.ErrInstanceNotFound
	}
	return nil
}

func optionalText(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}

func each[R any, T any](rows []R, parse func(R) (*T, error)) ([]*T, error) {
	out := make([]*T, 0, len(rows))
	for _, row := range rows {
		v, err := parse(row)
		if err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, nil
}

// storedGRNs parses GRNs a constraint already held, so a failure is the
// database's fault.
func storedGRNs(what string, values ...string) ([]grn.GRN, error) {
	out := make([]grn.GRN, 0, len(values))
	for _, v := range values {
		g, err := grn.Parse(v)
		if err != nil {
			return nil, errorx.Wrap(err, "stored "+what, errorx.KindInternal)
		}
		out = append(out, g)
	}
	return out, nil
}

func rowToApp(row db.App) (*app.App, error) {
	g, err := storedGRNs("app", row.Grn)
	if err != nil {
		return nil, err
	}
	return &app.App{
		GRN:                g[0],
		Slug:               row.Slug,
		Name:               row.Name,
		Description:        row.Description,
		Visibility:         app.Visibility(row.Visibility),
		RequestedActions:   row.RequestedActions,
		RequestsBotHosting: row.RequestsBotHosting,
		Instances:          app.Instances(row.Instances),
		Delivery:           app.Delivery(row.Delivery),
		MachineOperations:  row.MachineOperations,
		IssuerAudiences:    row.IssuerAudiences,
	}, nil
}

func rowToInstallation(row db.Installation) (*app.Installation, error) {
	g, err := storedGRNs("installation", row.Grn, row.OrgGrn, row.AppGrn, row.CreatedBy)
	if err != nil {
		return nil, err
	}
	scope := app.Scope{}
	if row.Scope == "projects" {
		projects, err := storedGRNs("installation project", row.ProjectGrns...)
		if err != nil {
			return nil, err
		}
		if scope, err = app.ProjectScope(g[1], projects); err != nil {
			return nil, errorx.Wrap(err, "stored installation scope", errorx.KindInternal)
		}
	}
	return &app.Installation{
		GRN:          g[0],
		Organization: g[1],
		App:          g[2],
		Incarnation:  row.Incarnation.String(),
		Scope:        scope,
		CreatedBy:    g[3],
		CreatedAt:    row.CreatedAt.Time.UTC(),
	}, nil
}

// rowToInstance parses a stored row. A GRN that InstanceGRN does not
// rebuild from its organization names no instance of it, and is
// refused as storage that broke its own constraint.
func rowToInstance(row db.Instance) (*app.Instance, error) {
	g, err := storedGRNs("instance", row.Grn, row.OrgGrn, row.InstallationGrn, row.CreatedBy)
	if err != nil {
		return nil, err
	}
	if want, err := app.InstanceGRN(g[1], g[0].Identifier); err != nil || want != g[0] {
		return nil, errorx.New(errorx.KindInternal, "stored instance: grn "+row.Grn+" is not an instance of "+row.OrgGrn)
	}
	return &app.Instance{
		GRN:          g[0],
		Organization: g[1],
		Installation: g[2],
		CreatedBy:    g[3],
		CreatedAt:    row.CreatedAt.Time.UTC(),
		Name:         row.Name,
		Description:  row.Description,
		Kind:         row.Kind,
	}, nil
}
